INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','nouns-and-plurals','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"nouns-and-plurals","title":"Nouns: singular, plural and irregular forms","level":"A1","order":2,"summary":"Recognise separate things, form their plurals and make nearby words agree with their number.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Regular plural endings","Irregular and unchanged plurals","Agreement around the noun","Plural form is not possession"],"rules":[{"title":"Regular plural endings","explanation":"Most countable nouns form a plural with **-s**. After endings such as -s, -sh, -ch and -x, we often add **-es**. After a consonant + y, replace y with **-ies**. After a vowel + y, keep y and add -s. The ending changes the noun’s number, not its ownership.","pattern":"book**s** · box**es** · cit**ies** · key**s**","commonMistakes":["An apostrophe does not normally make a plural: two books, not two book’s."],"examples":["Choose the ordinary plural phrase for individual books: “two **books**”.","Choose the ordinary plural phrase for individual boxes: “two **boxes**”."],"skill":"form"},{"title":"Irregular and unchanged plurals","explanation":"Some nouns change internally: man → men, tooth → teeth. Others have the same singular and plural form, such as sheep and species. Learn each noun with its plural. A word ending in -s is not automatically plural: news usually takes singular agreement.","pattern":"one **child**, two **children** · one **sheep**, two **sheep**","commonMistakes":["Fish is a common plural for individual fish; fishes can refer to different kinds. The practice specifies the ordinary count sense."],"examples":["Choose the verb: “These books **are** easy to recognise.”","Choose the verb: “These boxes **are** easy to recognise.”"],"skill":"meaning"},{"title":"Agreement around the noun","explanation":"Use **this / that / a / an** with a singular count noun and **these / those** with a plural. A plural noun used as subject normally takes a plural verb. The words around an unchanged noun can reveal its number.","pattern":"**These sheep are** calm. / **This sheep is** calm.","commonMistakes":["This books mixes a singular demonstrative with a plural noun."],"examples":["Point to one item: “**This** book is in the picture.”","Point to one item: “**This** box is in the picture.”"],"skill":"contrast"},{"title":"Plural form is not possession","explanation":"Distinguish plural -s from possessive ’s and s’. A plural noun says how many; a possessive marks a relationship. In two students’ bags, students is plural and the apostrophe marks possession. With an irregular plural, add ’s: children’s.","pattern":"two **students** · one **student’s** bag · two **students’** bags","commonMistakes":["Some nouns such as furniture are uncountable in their usual sense. Use pieces of furniture, not furnitures."],"examples":["Several books share the belongings. Choose the possessive spelling for the plural noun “books”. → **books''**","Several boxes share the belongings. Choose the possessive spelling for the plural noun “boxes”. → **boxes''**"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-nouns"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"6ce7070a-5d92-5ba4-a969-feecba001715","topicSlug":"nouns-and-plurals","level":"A1","prompt":"Choose the ordinary plural phrase for individual books: “two ____”.","choices":[{"id":"A","text":"books"},{"id":"B","text":"book''s"},{"id":"C","text":"books''"},{"id":"D","text":"bookses"}],"answerId":"A","hint":"Look at the number **two**, then recall the noun’s plural; an apostrophe is not a plural ending.","explanation":"The ordinary plural of **book** is **books**. The number two requires that plural sense.","keywords":["plural-form"],"skill":"plural-form","contextKey":"nouns-and-plurals-1","fingerprint":"acceeb66eaeedb2d242cddabcd068c589ea0ab152f0477f55d3294d01922bf79","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-nouns"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Look at the number **two**, then recall the noun’s plural; an apostrophe is not a plural ending.","The ordinary plural of **book** is **books**. The number two requires that plural sense.","Choose **books**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The ordinary plural of **book** is **books**. The number two requires that plural sense.","B":"Apostrophe + s marks possession, not a plural count.","C":"A possessive apostrophe is not needed to count these nouns.","D":"This adds an extra ending to the established plural form."}}},{"id":"b77cc0a5-4374-5c87-a38d-67f49168866a","topicSlug":"nouns-and-plurals","level":"A1","prompt":"Choose the verb: “These books ____ easy to recognise.”","choices":[{"id":"A","text":"be"},{"id":"B","text":"are"},{"id":"C","text":"is"},{"id":"D","text":"am"}],"answerId":"B","hint":"The demonstrative **these** makes the plural number explicit.","explanation":"**These books** is plural, so use **are**.","keywords":["plural-agreement"],"skill":"plural-agreement","contextKey":"nouns-and-plurals-1","fingerprint":"4a3a65c3da814228d56c5384b671dba9f09173fff36ca8ca7c29df0ce320d84a","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-nouns"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The demonstrative **these** makes the plural number explicit.","**These books** is plural, so use **are**.","Choose **are**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Be is not the finite present form required here.","B":"**These books** is plural, so use **are**.","C":"Is is singular and does not agree with these.","D":"Am agrees with I, not this plural noun phrase."}}},{"id":"14865f76-2b80-5d58-a771-1a3b88e91226","topicSlug":"nouns-and-plurals","level":"A1","prompt":"Point to one item: “____ book is in the picture.”","choices":[{"id":"A","text":"These"},{"id":"B","text":"Those"},{"id":"C","text":"Many"},{"id":"D","text":"This"}],"answerId":"D","hint":"Match the demonstrative to **one** item and the singular verb is.","explanation":"The instruction specifies one book, so the singular demonstrative is **this**.","keywords":["singular-demonstrative"],"skill":"singular-demonstrative","contextKey":"nouns-and-plurals-1","fingerprint":"9ca0fe4e0363409ff89b042cbb20a0381ce0153f6a6d506cc4175f94f6a915b1","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-nouns"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Match the demonstrative to **one** item and the singular verb is.","The instruction specifies one book, so the singular demonstrative is **this**.","Choose **This**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"These is plural, but the noun phrase refers to one item.","B":"Those is plural.","C":"Many requires a plural count noun and would not agree with is.","D":"The instruction specifies one book, so the singular demonstrative is **this**."}}},{"id":"589c4f24-20bc-5880-a795-0995a79f8365","topicSlug":"nouns-and-plurals","level":"A1","prompt":"Several books share the belongings. Choose the possessive spelling for the plural noun “books”.","choices":[{"id":"A","text":"books''"},{"id":"B","text":"books"},{"id":"C","text":"bookss''s"},{"id":"D","text":"books''s''"}],"answerId":"A","hint":"Find the plural noun’s final letter, then choose **apostrophe only** or **apostrophe + s**.","explanation":"The plural **books** already ends in s, so add only an apostrophe.","keywords":["plural-possession"],"skill":"plural-possession","contextKey":"nouns-and-plurals-1","fingerprint":"23780b0a19b3d685f8e2778f12cdecc28bedf5a4289cc5d85ba9d33a33c3953e","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-nouns"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Find the plural noun’s final letter, then choose **apostrophe only** or **apostrophe + s**.","The plural **books** already ends in s, so add only an apostrophe.","Choose **books''**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The plural **books** already ends in s, so add only an apostrophe.","B":"The possessive apostrophe is missing.","C":"This adds an extra plural-like s and the wrong possessive ending.","D":"Two apostrophes are not used for this possessive."}}},{"id":"b87fdcb4-bca5-5f54-a847-49b924ab06fc","topicSlug":"nouns-and-plurals","level":"A1","prompt":"Choose the ordinary plural phrase for individual boxes: “two ____”.","choices":[{"id":"A","text":"boxes"},{"id":"B","text":"box''s"},{"id":"C","text":"boxes''"},{"id":"D","text":"boxeses"}],"answerId":"A","hint":"Look at the number **two**, then recall the noun’s plural; an apostrophe is not a plural ending.","explanation":"The ordinary plural of **box** is **boxes**. The number two requires that plural sense.","keywords":["plural-form"],"skill":"plural-form","contextKey":"nouns-and-plurals-2","fingerprint":"a79ae697125697ef965c2aa0db50c35110ac63e7d1056031df7341ece0db5093","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-nouns"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Look at the number **two**, then recall the noun’s plural; an apostrophe is not a plural ending.","The ordinary plural of **box** is **boxes**. The number two requires that plural sense.","Choose **boxes**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The ordinary plural of **box** is **boxes**. The number two requires that plural sense.","B":"Apostrophe + s marks possession, not a plural count.","C":"A possessive apostrophe is not needed to count these nouns.","D":"This adds an extra ending to the established plural form."}}},{"id":"316bbec8-ee37-5408-af50-7c6ecc6d5aad","topicSlug":"nouns-and-plurals","level":"A1","prompt":"Choose the verb: “These boxes ____ easy to recognise.”","choices":[{"id":"A","text":"be"},{"id":"B","text":"are"},{"id":"C","text":"is"},{"id":"D","text":"am"}],"answerId":"B","hint":"The demonstrative **these** makes the plural number explicit.","explanation":"**These boxes** is plural, so use **are**.","keywords":["plural-agreement"],"skill":"plural-agreement","contextKey":"nouns-and-plurals-2","fingerprint":"c93d61ea82d42e92af258433e04851d9f6a82e82e075e333c977064e8ab018c3","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-nouns"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The demonstrative **these** makes the plural number explicit.","**These boxes** is plural, so use **are**.","Choose **are**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Be is not the finite present form required here.","B":"**These boxes** is plural, so use **are**.","C":"Is is singular and does not agree with these.","D":"Am agrees with I, not this plural noun phrase."}}},{"id":"751ae827-11ed-5862-a195-cd43683fc8b4","topicSlug":"nouns-and-plurals","level":"A1","prompt":"Point to one item: “____ box is in the picture.”","choices":[{"id":"A","text":"Those"},{"id":"B","text":"Many"},{"id":"C","text":"This"},{"id":"D","text":"These"}],"answerId":"C","hint":"Match the demonstrative to **one** item and the singular verb is.","explanation":"The instruction specifies one box, so the singular demonstrative is **this**.","keywords":["singular-demonstrative"],"skill":"singular-demonstrative","contextKey":"nouns-and-plurals-2","fingerprint":"7eea97d3992a0693634e241fe2cdc90543d466ed59917700f0e04430a2030fed","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-nouns"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Match the demonstrative to **one** item and the singular verb is.","The instruction specifies one box, so the singular demonstrative is **this**.","Choose **This**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Those is plural.","B":"Many requires a plural count noun and would not agree with is.","C":"The instruction specifies one box, so the singular demonstrative is **this**.","D":"These is plural, but the noun phrase refers to one item."}}},{"id":"81d006cb-e5b2-5746-a257-0965c4eee8b9","topicSlug":"nouns-and-plurals","level":"A1","prompt":"Several boxes share the belongings. Choose the possessive spelling for the plural noun “boxes”.","choices":[{"id":"A","text":"boxes''"},{"id":"B","text":"boxes"},{"id":"C","text":"boxess''s"},{"id":"D","text":"boxes''s''"}],"answerId":"A","hint":"Find the plural noun’s final letter, then choose **apostrophe only** or **apostrophe + s**.","explanation":"The plural **boxes** already ends in s, so add only an apostrophe.","keywords":["plural-possession"],"skill":"plural-possession","contextKey":"nouns-and-plurals-2","fingerprint":"7cb1ad6b436bcda40db74418786300fb9c911c2c9e3eb9b3fc9f89c95714b989","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-nouns"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"s